class.description:
Add a [TickObject] as a child of the node to synchronize (see [member root_path]) and extend it with a script. Declare the synchronized properties in [method _setup_sync], write the controller's input in [method _collect_input] and advance the object by one tick in [method _process_tick].
The server simulates the object with the input of its [member controller_peer]. That client predicts it; every other client interpolates it, or simulates it as a doll (see [member remote_mode]).
With [constant TickNetwork.AUTHORITY_DISTRIBUTED], the node that owns the object simulates it with its own input, and the other nodes interpolate it. The owner changes with [method request_authority], [method release_authority] and [method assign_authority].
[codeblock]
extends TickObject

func _setup_sync():
	declare_var("position", TickCodec.vector3(TickCodec.PRECISION_HALF))

func _collect_input(input: DataBuffer):
	input.add_vector2(Input.get_vector("left", "right", "up", "down"), DataBuffer.COMPRESSION_LEVEL_2)

func _process_tick(delta: float, input: DataBuffer):
	var direction := Vector2()
	if input.get_size() > 0:
		direction = input.read_vector2(DataBuffer.COMPRESSION_LEVEL_2)
	get_root_node().position += Vector3(direction.x, 0.0, direction.y) * 5.0 * delta
[/codeblock]
